 const requested={3:['出廠',r.minimum],8:['第 6 站',Math.min(...r.values.map(v=>v[5]))],43:['第 2 站',Math.min(...r.values.map(v=>v[1]))],45:['第 4 站',Math.min(...r.values.map(v=>v[3]))],54:['第 2 站',Math.min(...r.values.map(v=>v[1]))]}[n];
