function lcsDataExplanation(q,n){
 const stem=stemOf(q),x=stem.match(/S1\s*=\s*([A-Z]+)/)[1],y=stem.match(/S2\s*=\s*([A-Z]+)/)[1],r=longestCommonSubsequence(x,y);
 let text='核心觀念：\n依題名 LCS 計算「共同子序列」：字元可不連續，但順序不能改。題幹也用了「子字串」一詞；若它指必須連續的片段，就是另一個問題，不能直接套用這個結果。\n\nc[i,j] 是前 i 個字元與前 j 個字元的 LCS 長度。任一前綴為空，長度為 0；尾字元相同取左上值加 1，箭頭 LU；不相同則比較上方與左方，較大者決定方向。本組依虛擬碼「上方大於或等於左方」時選 U，所以平手向上。\n\n解題步驟：\n'+`橫向字串為 ${y}，每列數值依序對應 j=0 到 ${y.length}：\n`+r.table.map((row,i)=>`i=${i}${i?'（'+x[i-1]+'）':'（空）'}：${row.join(',')}`).join('\n');
 if(n===11||n===13){
  const cells=n===11?[[3,4],[4,6],[7,6]]:[[3,3],[4,4],[6,6]];
  text+='\n\n各填空位置的推導：\n'+cells.map(([i,j])=>x[i-1]===y[j-1]?`[${i},${j}]：尾字元同為 ${x[i-1]}，c[${i-1},${j-1}]+1=${r.table[i-1][j-1]}+1=${r.table[i][j]}，箭頭 LU。`:`[${i},${j}]：${x[i-1]} 與 ${y[j-1]} 不同，上方 c[${i-1},${j}]=${r.table[i-1][j]}，左方 c[${i},${j-1}]=${r.table[i][j-1]}，取 ${r.table[i][j]}，箭頭 ${r.arrows[i][j]}${r.table[i-1][j]===r.table[i][j-1]?'；平手按規則向上':''}。`).join('\n');
  text+='\n依題目順序，數值與箭頭依序填 '+cells.flatMap(([i,j])=>[r.table[i][j],r.arrows[i][j]]).join('/')+'。';
 }else{
  text+='\n\n回溯步驟：\n'+r.trace.map(step=>`[${step.i},${step.j}] 長度 ${step.value}，走 ${step.direction}${step.character?'，收集字元 '+step.character:''}。`).join('\n')+`\n從右下回頭收集到 ${r.trace.map(step=>step.character).join('')}，反轉後為 ${r.sequence}，長度 ${r.length}。`;
  if(n===2)text+='同長度的共同子序列可能不只一個；此處是依上述箭頭與平手規則重建出的 BCBA。';
  if(n===44){text+='\n\n條件與答案差異：\n目前收錄 ABZD，但第二個字串 BACZDBA 中，Z 之前只有開頭的 B；若先取位置 2 的 A，再取後面的 B，只能到位置 6，已越過位置 4 的 Z，所以 ABZD 不是它的子序列。依表格與回溯可得到 BAZD：第一字串取位置 2、3、4、5，第二字串取位置 1、2、4、5。原答案保留，但這個順序差異不能忽略。';return {text,result:r,issue:'lcs-sequence-not-subsequence',terminologyNote:true};}
 }
 return {text,result:r,terminologyNote:true};
}
function codeExplanation(q,n){
 if(n===38||n===53){
  const intro='核心觀念：\n矩陣鏈的狀態是區間 m[i,j]。單一矩陣不需相乘，所以 m[i,i]=0；區間長度 l 從 2 到 n。固定 l 時，起點 i 從 1 到 n−l+1，才會使 j=i+l−1 不超出 n。\n\n解題步驟：\n對每個區間，最後一次相乘必在 k 與 k+1 間切開，k 必須從 i 到 j−1，確保左右兩邊都非空。每個 k 比較 m[i,k]+m[k+1,j]+p[i−1]×p[k]×p[j]，有更小值就更新 m 與切點 s。\n\n例如 n=4、l=3，只能算區間 [1,3] 與 [2,4]；若把起點上界寫成 n−l−1 就會漏掉所有這種區間。若讓 k 到 j+1，則會產生空區間或越界。共有 Θ(n²) 個區間，每個至多比較 Θ(n) 個切點，標準演算法總時間 Θ(n³)，因此 O(n³) 也是正確上界。';
  return {text:intro+'\n\n'+optionReview(q,n===38?['此上界讓區間終點不超過 n，而且不漏掉最後一段。','與三層依賴迴圈的總成本一致。','最後切點必須留一個以上矩陣在左右兩側，範圍正確。','從長度 2 開始，直到整條鏈長度 n，順序正確。']:['切點不能越過 j−1；到 j+1 會含空區間及越界。','標準區間動態規劃的上界是 O(n³)。','先算短區間再算長區間，範圍正確。','應是 n−l+1；減 1 會漏掉合法區間，甚至讓應計算的迴圈變空。'])};
 }
 if(n===21)return {text:'核心觀念：\nPRINT_LCS 使用先前保存的箭頭重建字串，不再重新比較所有可能長度。到第 0 列或第 0 欄便停止。走左上表示本格尾字元相同，必須先處理較短前綴，再輸出目前字元，才能保有原本順序。\n\n解題步驟：\n在標記 C 的位置，上一行已遞迴到 (i−1,j−1)，因此接著應 print xi。在向上箭頭的分支，略過 X 的第 i 個字元，所以標記 B 應呼叫 PRINT_LCS(b,X,i−1,j)。走左箭頭則只減 j。每一步至少減少 i 或 j，才能朝邊界終止。\n\n'+optionReview(q,['此處已經處理左上前綴，還應輸出匹配的字元；再呼叫向上的遞迴會重複錯誤分支，也沒有輸出字元。','先遞迴輸出較前面的共同字元，再輸出 xi，順序正確。','向上應減少 i，不能增加 i；i+1 可能超出目前前綴，與箭頭方向相反。','略過 X 的最後一個字元，保持 Y 的前綴不變，正是向上分支。'])};
 const common='核心觀念：\nc[i,j] 保存 LCS 長度，b[i,j] 保存回溯箭頭。若 xi=yj，取左上角前綴的長度加 1；若不同，取上方與左方兩者中較大的長度。這裡比較的是不同前綴，不能把上方拿來和它自己比。\n\n解題步驟：\n相同字元：c[i,j]=c[i−1,j−1]+1，箭頭左上。\n不同字元：若 c[i−1,j]≥c[i,j−1]，取上方並畫向上；否則取左方 c[i,j−1] 並畫向左。\n例如 X=A、Y=AB，在格 [1,2] 尾字元不同，上方為 0、左方為 1，必須取左方 1。填完後回傳長度表 c 與方向表 b，之後才能重建字串。';
 if(n===48)return {text:common+'\n\n依兩個填空的位置，第一格是尾字元相同時的 c[i-1,j-1]+1；第二格是左方 c[i,j-1]。依要求去掉空白，以 / 分隔為 c[i-1,j-1]+1/c[i,j-1]。'};
 if(n===47)return {text:common+'\n\n'+optionReview(q,['相同字元把共同前綴的長度加 1，正確。','不相同且左方較大時取左方，正確。','依同單元已列出的 return c and b 介面，應同時回傳長度表與方向表；只寫 b 會少掉長度表。若另行設計只回傳方向的函式，那是另一種介面，不是這組標準虛擬碼的完整回傳資料。','這裡必須是左方值，才能與上方比較，正確。'])};
 return {text:common+'\n\n'+optionReview(q,['這是左方值，不是相同字元時應取的左上加 1。','它是某個長度計算式，不能代替回傳 c 與 b 兩張表。','照此選項會變成 c[i−1,j]≥c[i−1,j]，永遠成立；在 X=A、Y=AB 的格 [1,2] 會錯取 0，漏掉左方的 1。應比較 c[i,j−1]。','不相同且左方較大時，取這個左方值，正確。'])+'\n\n條件與答案差異：\n目前收錄答案包含「BBB 是 c[i-1, j]」，但它會使比較變成自己大於或等於自己，與題面後續的向左分支及 LCS 轉移不一致。原答案保留，以上用具體前綴反例說明差異。',issue:'lcs-comparison-formula'};
}
function knapsackExplanation(){
 const items=[{weight:4,value:4500},{weight:5,value:5700},{weight:2,value:2250},{weight:1,value:1100},{weight:6,value:6700}],r=knapsack01(items,8),names=['李子','蘋果','橘子','草莓','甜瓜'];
 return {text:'核心觀念：\n將表中的每筆水果視為一件、每件最多取一次，且不能切割，因此是 0/1 背包。令 V[i,w] 表示只用前 i 件、容量不超過 w 的最高總價。先比較不拿這件的 V[i−1,w]；若放得下，再比較拿它一次的 V[i−1,w−重量]+價值。兩者都讀上一列，避免同一件重複拿。\n\n解題步驟：\n以下每列依序是容量 0 到 8 公斤的最高總價：\n未拿任何水果：'+r.table[0].join(',')+'\n'+r.table.slice(1).map((row,i)=>'加入'+names[i]+'後：'+row.join(',')).join('\n')+'\n\n回溯物品：\n加入甜瓜後，容量 8 的最佳值仍是 9050，所以不拿甜瓜。拿草莓後，剩容量 7、尚需價值 7950；拿橘子後，剩容量 5、尚需 5700；再拿蘋果便完成。總重量 1+2+5=8，總價 1100+2250+5700=9050。甜瓜加橘子雖也剛好 8 公斤，價值為 6700+2250=8950，仍少 100。\n\n水果編號按題表為蘋果 1、橘子 2、草莓 3，由小到大寫 123，兩格依序是 9050/123。',result:r};
}
export function buildL10Review(){return {schema:1,course:'algorithms',unit:'L10',date:'2026-11-27',questions:before.questions.map((row,index)=>{
 const n=index+1,q=row.question;let reviewed,category;
 if(concepts[n]){const [core,example,comments]=concepts[n];reviewed={text:'核心觀念：\n'+core+'\n\n解題步驟：\n'+example+(comments.length?'\n\n'+optionReview(q,comments):'')};category=/裝配線/.test(stemOf(q))?'裝配線排程':'動態規劃基礎';if([7,32,50].includes(n))reviewed.conditionNote=true;if(n===50)reviewed.text+='\n\n適用條件：\n若題幹只是問能否存放狀態，樹與鏈結串列也能實作查表，只是查找成本與配置方式不同。本題沒有明列常用形式或效率限制，因此不能把未列入正解的資料結構解讀成完全不能儲存。原答案保留，以上區分常用實作與理論可行性。';}
 else if(/裝配線/.test(stemOf(q))){reviewed=assemblyExplanation(q,n);category='裝配線排程';}
 else if(/Matrix/.test(stemOf(q))){reviewed=matrixExplanation(q,n);category='矩陣鏈乘法';}
 else if(/已知S1/.test(stemOf(q))){reviewed=lcsDataExplanation(q,n);category='最長共同子序列';}
 else if(n===22){reviewed=knapsackExplanation();category='0/1 背包問題';}
 else{reviewed=codeExplanation(q,n);category=/MATRIX_CHAIN/.test(stemOf(q))?'矩陣鏈乘法':'最長共同子序列';}
 if(!reviewed?.text)throw Error('Missing explanation '+row.id);
 return {id:row.id,expectedRevision:row.revision,category:['','HTML 匯入','其他'].includes(q.category??'')?category:q.category,explanation:reviewed.text,...(reviewed.issue?{issue:reviewed.issue}:{}),...(reviewed.indexNote?{indexNote:true}:{}),...(reviewed.terminologyNote?{terminologyNote:true}:{}),...(reviewed.conditionNote?{conditionNote:true}:{}),...(reviewed.result?{calculation:reviewed.result}:{})};
})};}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){const review=buildL10Review();await writeFile(new URL('content/algorithms-l10-review-20261127.json',root),JSON.stringify(review,null,2)+'\n');console.log(JSON.stringify({reviewed:review.questions.length,issues:review.questions.filter(q=>q.issue).map(q=>({id:q.id,issue:q.issue})),topics:[...new Set(review.questions.map(q=>q.category))]}));}
